const handleLogin = async (e) => {
    e.preventDefault();
    setError(""); // Clear previous error
  
    try {
      const rawData = {
        userid: email,
        password: password,
      };
  
      const apiURL = `https://novaoffice.novasoftwares.com/service.aspx?ApiVer=1&Devid=online&AppId=NV01&Lat=0&Lng=0&Control=auth&data=${encodeURIComponent(JSON.stringify(rawData))}`;
  
      const response = await fetch(apiURL);
      const data = await response.json();
  
      console.log("API Response:", data);
  
      if (data?.Response?.Status === "1") {
        // Pass fetched data to Dashboard using navigate
        navigate("/dashboard", { state: { data } });
      } else {
        setError("Invalid credentials. Try again.");
      }
    } catch (err) {
      console.error("Login error:", err);
      setError("Something went wrong. Please try again.");
    }
  };
